def list_running_processes(filter=None, **_extra):
    import json, os, datetime, subprocess, platform, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0455000" if __import__("os").path.isdir("./environment_mix/0455000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _choose_api_key():
        # Ambient auth: pick any api key that can serve requests; do not require client-provided credential.
        keys = _load("api_keys.json")
        sets = _load("allowed_command_sets.json")
        sets_by_id = {r.get("id"): r for r in sets if isinstance(r, dict)}
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            s = sets_by_id.get(k.get("allowed_command_set_id"))
            if not s:
                continue
            # Inventory tools not gated by allowlists; only require an active key and a valid policy reference.
            return k, s
        return None, None

    def _rate_limited(api_key_row):
        inv = _load("tool_invocations.json")
        limit = api_key_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1:
            # Schema says >=1; treat invalid stored config as unauthorized-capability.
            return True, limit, 0
        now = _now()
        cutoff = now - datetime.timedelta(minutes=1)
        cnt = 0
        for r in inv:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt >= limit, limit, cnt

    t0 = time.time()
    api_key_row, _policy = _choose_api_key()
    if not api_key_row:
        # No usable key/policy combo exists in store.
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    # Validate request params (schema: only 'filter' optional string)
    if filter is not None and not isinstance(filter, str):
        # Log rejected invocation with VALIDATION_ERROR
        invocations = _load("tool_invocations.json")
        now = _now()
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "api_key_id": api_key_row.get("id"),
            "tool_name": "list_running_processes",
            "request_params": {"filter": filter},
            "status": "rejected",
            "started_at": None,
            "ended_at": _iso(now),
            "duration_ms": 0,
            "result_truncated": False,
            "error_code": "VALIDATION_ERROR",
            "error_message": "filter must be a string when provided.",
            "client_ip": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        invocations.append(inv_row)
        _save("tool_invocations.json", invocations)
        return _err("VALIDATION_ERROR", "filter must be a string when provided.")

    # Rate limit check (before recording? real systems often record rejections too; record after decision, but count prior invocations)
    limited, limit, used = _rate_limited(api_key_row)
    if limited:
        invocations = _load("tool_invocations.json")
        now = _now()
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "api_key_id": api_key_row.get("id"),
            "tool_name": "list_running_processes",
            "request_params": {"filter": filter},
            "status": "rejected",
            "started_at": None,
            "ended_at": _iso(now),
            "duration_ms": 0,
            "result_truncated": False,
            "error_code": "RATE_LIMIT",
            "error_message": "Rate limit exceeded.",
            "client_ip": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        invocations.append(inv_row)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=limit, used_in_last_minute=used)

    # Create invocation (received -> running -> succeeded/failed)
    invocations = _load("tool_invocations.json")
    now = _now()
    inv_id = _gen_id("inv")
    req_params = {"filter": filter}
    inv_row = {
        "id": inv_id,
        "api_key_id": api_key_row.get("id"),
        "tool_name": "list_running_processes",
        "request_params": req_params,
        "status": "received",
        "started_at": None,
        "ended_at": None,
        "duration_ms": None,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "client_ip": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    invocations.append(inv_row)
    _save("tool_invocations.json", invocations)

    # Transition to running
    started = _now()
    for r in invocations:
        if isinstance(r, dict) and r.get("id") == inv_id:
            r["status"] = "running"
            r["started_at"] = _iso(started)
            r["updated_at"] = _iso(_now())
            break
    _save("tool_invocations.json", invocations)

    # Execute live OS query
    try:
        processes = []
        sysname = platform.system().lower()
        if "windows" in sysname:
            # Use tasklist CSV; robust parsing
            cmd = ["tasklist", "/FO", "CSV", "/NH"]
            cp = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
            out = cp.stdout or ""
            # CSV lines like: "Image Name","PID","Session Name","Session#","Mem Usage"
            # parse minimally to name,pid
            import csv
            from io import StringIO
            reader = csv.reader(StringIO(out))
            for row in reader:
                if not row or len(row) < 2:
                    continue
                name = row[0]
                pid_s = row[1]
                try:
                    pid = int(pid_s)
                except Exception:
                    pid = None
                processes.append({"name": name, "pid": pid})
        else:
            # POSIX fallback
            cp = subprocess.run(["ps", "-eo", "pid=,comm="], capture_output=True, text=True, timeout=10)
            out = cp.stdout or ""
            for line in out.splitlines():
                line = line.strip()
                if not line:
                    continue
                parts = line.split(None, 1)
                if len(parts) != 2:
                    continue
                try:
                    pid = int(parts[0])
                except Exception:
                    pid = None
                name = parts[1].strip()
                processes.append({"name": name, "pid": pid})

        if isinstance(filter, str) and filter != "":
            needle = filter.lower()
            processes = [p for p in processes if isinstance(p, dict) and isinstance(p.get("name"), str) and needle in p["name"].lower()]

        ended = _now()
        dur_ms = int((ended - started).total_seconds() * 1000)

        # Update invocation: succeeded
        for r in invocations:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r["status"] = "succeeded"
                r["ended_at"] = _iso(ended)
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(_now())
                break
        _save("tool_invocations.json", invocations)

        # Update api key last_used_at on successful authenticated request
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = _iso(_now())
                k["updated_at"] = _iso(_now())
                break
        _save("api_keys.json", keys)

        return {
            "processes": processes,
            "count": len(processes),
            "invocation_id": inv_id,
        }
    except subprocess.TimeoutExpired:
        ended = _now()
        dur_ms = int((ended - started).total_seconds() * 1000)
        invocations = _load("tool_invocations.json")
        for r in invocations:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r["status"] = "failed"
                r["ended_at"] = _iso(ended)
                r["duration_ms"] = dur_ms
                r["error_code"] = "TIMEOUT"
                r["error_message"] = "Process listing timed out."
                r["updated_at"] = _iso(_now())
                break
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "Process listing timed out.", invocation_id=inv_id)
    except Exception as e:
        ended = _now()
        dur_ms = int((ended - started).total_seconds() * 1000)
        invocations = _load("tool_invocations.json")
        for r in invocations:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r["status"] = "failed"
                r["ended_at"] = _iso(ended)
                r["duration_ms"] = dur_ms
                r["error_code"] = "INTERNAL_ERROR"
                r["error_message"] = "Failed to list running processes."
                r["updated_at"] = _iso(_now())
                break
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "Failed to list running processes.", invocation_id=inv_id, detail=str(e)[:500])

def get_system_info(detail=None, **_extra):
    import json, os, datetime, subprocess, platform, time, getpass, socket

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0455000" if __import__("os").path.isdir("./environment_mix/0455000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
           	    return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _choose_api_key():
        keys = _load("api_keys.json")
        sets = _load("allowed_command_sets.json")
        sets_by_id = {r.get("id"): r for r in sets if isinstance(r, dict)}
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            s = sets_by_id.get(k.get("allowed_command_set_id"))
            if not s:
                continue
            return k, s
        return None, None

    def _rate_limited(api_key_row):
        inv = _load("tool_invocations.json")
        limit = api_key_row.get("rate_limit_per_minute")
        if not isinstance(limit, int) or limit < 1:
            return True, limit, 0
        now = _now()
        cutoff = now - datetime.timedelta(minutes=1)
        cnt = 0
        for r in inv:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt >= limit, limit, cnt

    api_key_row, _policy = _choose_api_key()
    if not api_key_row:
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")

    # Validate detail
    if detail is None:
        detail = "basic"
    if not isinstance(detail, str):
        # log rejected
        invocations = _load("tool_invocations.json")
        now = _now()
        inv_id = _gen_id("inv")
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key_row.get("id"),
            "tool_name": "get_system_info",
            "request_params": {"detail": detail},
            "status": "rejected",
            "started_at": None,
            "ended_at": _iso(now),
            "duration_ms": 0,
            "result_truncated": False,
            "error_code": "VALIDATION_ERROR",
            "error_message": "detail must be a string.",
            "client_ip": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("tool_invocations.json", invocations)
        return _err("VALIDATION_ERROR", "detail must be a string.")
    if detail not in ("basic", "full"):
        invocations = _load("tool_invocations.json")
        now = _now()
        inv_id = _gen_id("inv")
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key_row.get("id"),
            "tool_name": "get_system_info",
            "request_params": {"detail": detail},
            "status": "rejected",
            "started_at": None,
            "ended_at": _iso(now),
            "duration_ms": 0,
            "result_truncated": False,
            "error_code": "VALIDATION_ERROR",
            "error_message": "detail must be one of: basic, full.",
            "client_ip": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("tool_invocations.json", invocations)
        return _err("VALIDATION_ERROR", "detail must be one of: basic, full.")

    limited, limit, used = _rate_limited(api_key_row)
