        invocations = _load("tool_invocations.json")
        now = _now()
        inv_id = _gen_id("inv")
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key_row.get("id"),
            "tool_name": "get_system_info",
            "request_params": {"detail": detail},
            "status": "rejected",
            "started_at": None,
            "ended_at": _iso(now),
            "duration_ms": 0,
            "result_truncated": False,
            "error_code": "RATE_LIMIT",
            "error_message": "Rate limit exceeded.",
            "client_ip": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=limit, used_in_last_minute=used)

    invocations = _load("tool_invocations.json")
    now = _now()
    inv_id = _gen_id("inv")
    inv_row = {
        "id": inv_id,
        "api_key_id": api_key_row.get("id"),
        "tool_name": "get_system_info",
        "request_params": {"detail": detail},
        "status": "received",
        "started_at": None,
        "ended_at": None,
        "duration_ms": None,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "client_ip": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    invocations.append(inv_row)
    _save("tool_invocations.json", invocations)

    started = _now()
    for r in invocations:
        if isinstance(r, dict) and r.get("id") == inv_id:
            r["status"] = "running"
            r["started_at"] = _iso(started)
            r["updated_at"] = _iso(_now())
            break
    _save("tool_invocations.json", invocations)

    try:
        info = {
            "hostname": socket.gethostname(),
            "fqdn": socket.getfqdn(),
            "os": {
                "system": platform.system(),
                "release": platform.release(),
                "version": platform.version(),
                "platform": platform.platform(),
                "arch": platform.machine(),
            },
            "python": {
                "implementation": platform.python_implementation(),
                "version": platform.python_version(),
            },
            "user": {
                "name": getpass.getuser(),
            },
        }

        if detail == "full":
            # Add richer details where available
            info["hardware"] = {
                "processor": platform.processor(),
                "cpu_count": os.cpu_count(),
            }
            # Windows: systeminfo output is large; keep small subset
            sysname = platform.system().lower()
            if "windows" in sysname:
                try:
                    cp = subprocess.run(["cmd", "/c", "ver"], capture_output=True, text=True, timeout=10)
                    info["windows"] = {"ver": (cp.stdout or "").strip()}
                except Exception:
                    info["windows"] = {"ver": None}
            try:
                info["env"] = {
                    "username": os.environ.get("USERNAME"),
                    "userdomain": os.environ.get("USERDOMAIN"),
                    "computername": os.environ.get("COMPUTERNAME"),
                }
            except Exception:
                info["env"] = {}

        ended = _now()
        dur_ms = int((ended - started).total_seconds() * 1000)
        invocations = _load("tool_invocations.json")
        for r in invocations:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r["status"] = "succeeded"
                r["ended_at"] = _iso(ended)
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(_now())
                break
        _save("tool_invocations.json", invocations)

        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = _iso(_now())
                k["updated_at"] = _iso(_now())
                break
        _save("api_keys.json", keys)

        return {"detail": detail, "system": info, "invocation_id": inv_id}
    except Exception as e:
        ended = _now()
        dur_ms = int((ended - started).total_seconds() * 1000)
        invocations = _load("tool_invocations.json")
        for r in invocations:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r["status"] = "failed"
                r["ended_at"] = _iso(ended)
                r["duration_ms"] = dur_ms
                r["error_code"] = "INTERNAL_ERROR"
                r["error_message"] = "Failed to collect system info."
                r["updated_at"] = _iso(_now())
                break
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "Failed to collect system info.", invocation_id=inv_id, detail=str(e)[:500])

def get_network_info(networkInterface=None, **_extra):
    import json, os, datetime, time, platform, subprocess, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0455000" if __import__("os").path.isdir("./environment_mix/0455000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import secrets
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _choose_key_for_call():
        keys = _load("api_keys.json")
        sets = _load("allowed_command_sets.json")
        sets_by_id = {r.get("id"): r for r in sets if isinstance(r, dict)}
        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            # read tools require only active key; but prefer ones with a policy row
            sid = k.get("allowed_command_set_id")
            candidates.append((k, sets_by_id.get(sid)))
        if not candidates:
            return None, None
        # Prefer keys whose policy exists and is active (best "working combination")
        for k, s in candidates:
            if isinstance(s, dict) and s.get("status") == "active":
                return k, s
        for k, s in candidates:
            if isinstance(s, dict):
                return k, s
        return candidates[0][0], candidates[0][1]

    def _count_invocations_last_minute(invocations, api_key_id, now_dt):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in invocations:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt

    t0 = time.time()

    # Validate input
    if networkInterface is not None and not isinstance(networkInterface, str):
        return _err("VALIDATION_ERROR", "networkInterface must be a string")

    api_key, _policy = _choose_key_for_call()
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available")

    invocations = _load("tool_invocations.json")
    now_dt = _now()

    # Rate limit (rolling minute) - reject with RATE_LIMIT
    try:
        rlim = int(api_key.get("rate_limit_per_minute"))
    except Exception:
        rlim = None
    if rlim is None or rlim < 1 or rlim > 6000:
        # Misconfigured key in store; treat as UNAUTHORIZED to avoid bypass
        return _err("UNAUTHORIZED", "No API key with a valid rate limit configuration available")
    used = _count_invocations_last_minute(invocations, api_key.get("id"), now_dt)
    if used >= rlim:
        inv_id = _ulid("wcmcp_inv_")
        now_iso = _iso(now_dt)
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key.get("id"),
            "tool_name": "get_network_info",
            "request_params": {"networkInterface": networkInterface},
            "status": "rejected",
            "started_at": None,
            "ended_at": now_iso,
            "duration_ms": int((time.time() - t0) * 1000),
            "result_truncated": False,
            "error_code": "RATE_LIMIT",
            "error_message": "Rate limit exceeded for this API key.",
            "client_ip": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT", invocation_id=inv_id)

    # Create invocation (received -> running -> succeeded/failed)
    inv_id = _ulid("wcmcp_inv_")
    now_iso = _iso(now_dt)
    inv_row = {
        "id": inv_id,
        "api_key_id": api_key.get("id"),
        "tool_name": "get_network_info",
        "request_params": {"networkInterface": networkInterface},
        "status": "received",
        "started_at": None,
        "ended_at": None,
        "duration_ms": None,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "client_ip": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    invocations.append(inv_row)
    _save("tool_invocations.json", invocations)

    # Transition to running
    started = _iso(_now())
    inv_row["status"] = "running"
    inv_row["started_at"] = started
    inv_row["updated_at"] = started
    _save("tool_invocations.json", invocations)

    try:
        system = platform.system().lower()
        results = []

        if system == "windows":
            # Use PowerShell to produce structured JSON of adapter config.
            ps = [
                "powershell",
                "-NoProfile",
                "-NonInteractive",
                "-Command",
                "Get-NetIPConfiguration | Select-Object InterfaceAlias,InterfaceDescription,NetAdapter.Status,IPv4Address,IPv6Address,DNSServer,Ipv4DefaultGateway,Ipv6DefaultGateway | ConvertTo-Json -Depth 5"
            ]
            proc = subprocess.run(ps, capture_output=True, text=True, timeout=20)
            if proc.returncode == 0 and proc.stdout.strip():
                try:
                    data = json.loads(proc.stdout)
                    if isinstance(data, dict):
                        data = [data]
                    if isinstance(data, list):
                        for item in data:
                            if not isinstance(item, dict):
                                continue
                            # Normalize fields into a stable envelope
                            alias = item.get("InterfaceAlias")
                            desc = item.get("InterfaceDescription")
                            status = None
                            na = item.get("NetAdapter")
                            if isinstance(na, dict):
                                status = na.get("Status")
                            ipv4 = item.get("IPv4Address")
                            ipv6 = item.get("IPv6Address")
                            dns = item.get("DNSServer")
                            gw4 = item.get("Ipv4DefaultGateway")
                            gw6 = item.get("Ipv6DefaultGateway")

                            def _ip_list(v):
                                out = []
                                if isinstance(v, dict):
                                    v = [v]
                                if isinstance(v, list):
                                    for x in v:
                                        if isinstance(x, dict) and x.get("IPAddress"):
                                            out.append(x.get("IPAddress"))
                                return out

                            def _dns_list(v):
                                if isinstance(v, dict):
                                    # sometimes {ServerAddresses:[...]}
                                    sa = v.get("ServerAddresses")
                                    if isinstance(sa, list):
                                        return [str(x) for x in sa]
                                if isinstance(v, list):
                                    # sometimes list of strings/dicts
                                    out = []
                                    for x in v:
                                        if isinstance(x, str):
                                            out.append(x)
                                        elif isinstance(x, dict):
                                            sa = x.get("ServerAddresses")
                                            if isinstance(sa, list):
                                                out.extend([str(a) for a in sa])
                                    return out
                                return []

                            def _gw(v):
                                if isinstance(v, dict) and v.get("NextHop"):
                                    return v.get("NextHop")
                                if isinstance(v, list) and v:
                                    for x in v:
                                        if isinstance(x, dict) and x.get("NextHop"):
                                            return x.get("NextHop")
                                return None

                            results.append({
                                "name": alias,
                                "description": desc,
                                "status": status,
                                "ipv4_addresses": _ip_list(ipv4),
                                "ipv6_addresses": _ip_list(ipv6),
                                "dns_servers": _dns_list(dns),
                                "gateway_ipv4": _gw(gw4),
                                "gateway_ipv6": _gw(gw6),
                            })
                except Exception:
                    # fall back below
                    results = []

            if not results:
                # Fallback: ipconfig output, best-effort parse into blocks
                proc = subprocess.run(["ipconfig", "/all"], capture_output=True, text=True, timeout=20)
                txt = (proc.stdout or "") + "\n" + (proc.stderr or "")
                # Split by adapter headers
                blocks = re.split(r"\r?\n\r?\n", txt)
                cur = None
                parsed = []
                for b in blocks:
                    if "adapter" in b.lower() and ":" in b:
                        # header line
                        lines = [ln.rstrip() for ln in b.splitlines() if ln.strip()]
                        if not lines:
                            continue
                        header = lines[0]
                        name = header.split("adapter", 1)[-1].strip(" :")
                        cur = {"name": name, "raw": b[:20000]}
                        parsed.append(cur)
                results = [{"name": r.get("name"), "raw": r.get("raw")} for r in parsed]

        else:
            # Non-Windows: return empty inventory; should be data, not error
            results = []

        if networkInterface:
            # Filter by exact match (case-insensitive) on "name" when available
            ni = networkInterface.strip().lower()
            filtered = []
            for r in results:
                nm = r.get("name")
                if isinstance(nm, str) and nm.strip().lower() == ni:
                    filtered.append(r)
            results = filtered

        ended = _iso(_now())
        inv_row["status"] = "succeeded"
        inv_row["ended_at"] = ended
        inv_row["duration_ms"] = int((time.time() - t0) * 1000)
        inv_row["updated_at"] = ended
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                k["last_used_at"] = ended
                k["updated_at"] = ended
                break
        _save("api_keys.json", api_keys)
        _save("tool_invocations.json", invocations)
        return {
            "invocation_id": inv_id,
            "networkInterface": networkInterface,
            "interfaces": results
        }
    except subprocess.TimeoutExpired:
        ended = _iso(_now())
        inv_row["status"] = "failed"
        inv_row["ended_at"] = ended
        inv_row["duration_ms"] = int((time.time() - t0) * 1000)
        inv_row["error_code"] = "TIMEOUT"
        inv_row["error_message"] = "Network query timed out."
        inv_row["updated_at"] = ended
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "Network query timed out.", error_code="TIMEOUT", invocation_id=inv_id)
    except Exception as e:
        ended = _iso(_now())
        inv_row["status"] = "failed"
        inv_row["ended_at"] = ended
        inv_row["duration_ms"] = int((time.time() - t0) * 1000)
        inv_row["error_code"] = "FAILED"
        inv_row["error_message"] = str(e)[:500]
        inv_row["updated_at"] = ended
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "Failed to retrieve network info.", error_code="FAILED", invocation_id=inv_id)

def get_service_info(action=None, serviceName=None, **_extra):
    import json, os, datetime, time, platform, subprocess, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0455000" if __import__("os").path.isdir("./environment_mix/0455000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import secrets
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _choose_key_for_call():
        keys = _load("api_keys.json")
        sets = _load("allowed_command_sets.json")
        sets_by_id = {r.get("id"): r for r in sets if isinstance(r, dict)}
        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            candidates.append((k, sets_by_id.get(k.get("allowed_command_set_id"))))
        if not candidates:
            return None, None
        for k, s in candidates:
            if isinstance(s, dict) and s.get("status") == "active":
                return k, s
        for k, s in candidates:
            if isinstance(s, dict):
                return k, s
        return candidates[0][0], candidates[0][1]

    def _count_invocations_last_minute(invocations, api_key_id, now_dt):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in invocations:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt

    t0 = time.time()

    if action is None:
        action = "query"
    if not isinstance(action, str):
        return _err("VALIDATION_ERROR", "action must be a string")
    if action not in ("query", "status"):
        return _err("VALIDATION_ERROR", "action must be one of: query, status")
    if serviceName is not None and not isinstance(serviceName, str):
        return _err("VALIDATION_ERROR", "serviceName must be a string")
    if action == "status" and (serviceName is None or not isinstance(serviceName, str) or not serviceName.strip()):
        # Must be logged as rejected invocation per business rules
        api_key, _ = _choose_key_for_call()
        if not api_key:
            return _err("UNAUTHORIZED", "No active API key available")
        invocations = _load("tool_invocations.json")
        now_dt = _now()
        inv_id = _ulid("wcmcp_inv_")
        now_iso = _iso(now_dt)
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key.get("id"),
            "tool_name": "get_service_info",
            "request_params": {"action": action, "serviceName": serviceName},
            "status": "rejected",
            "started_at": None,
            "ended_at": now_iso,
            "duration_ms": int((time.time() - t0) * 1000),
            "result_truncated": False,
            "error_code": "VALIDATION_ERROR",
            "error_message": "serviceName is required when action='status'.",
            "client_ip": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_invocations.json", invocations)
        return _err("VALIDATION_ERROR", "serviceName is required when action='status'.", error_code="VALIDATION_ERROR", invocation_id=inv_id)

    api_key, _policy = _choose_key_for_call()
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available")

    invocations = _load("tool_invocations.json")
    now_dt = _now()

    # Rate limit
    try:
        rlim = int(api_key.get("rate_limit_per_minute"))
    except Exception:
        rlim = None
    if rlim is None or rlim < 1 or rlim > 6000:
        return _err("UNAUTHORIZED", "No API key with a valid rate limit configuration available")
    used = _count_invocations_last_minute(invocations, api_key.get("id"), now_dt)
    if used >= rlim:
        inv_id = _ulid("wcmcp_inv_")
        now_iso = _iso(now_dt)
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key.get("id"),
            "tool_name": "get_service_info",
            "request_params": {"action": action, "serviceName": serviceName},
            "status": "rejected",
            "started_at": None,
            "ended_at": now_iso,
            "duration_ms": int((time.time() - t0) * 1000),
            "result_truncated": False,
            "error_code": "RATE_LIMIT",
            "error_message": "Rate limit exceeded for this API key.",
            "client_ip": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT", invocation_id=inv_id)

    inv_id = _ulid("wcmcp_inv_")
    now_iso = _iso(now_dt)
    inv_row = {
        "id": inv_id,
        "api_key_id": api_key.get("id"),
        "tool_name": "get_service_info",
        "request_params": {"action": action, "serviceName": serviceName},
        "status": "received",
        "started_at": None,
        "ended_at": None,
        "duration_ms": None,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "client_ip": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    invocations.append(inv_row)
    _save("tool_invocations.json", invocations)

    # running
    started = _iso(_now())
    inv_row["status"] = "running"
    inv_row["started_at"] = started
    inv_row["updated_at"] = started
    _save("tool_invocations.json", invocations)

    try:
        if platform.system().lower() != "windows":
            # Must return data, not error (audit defect fix)
            services = []
        else:
            if action == "query":
                # Use PowerShell for structured output when possible
                ps = [
                    "powershell",
                    "-NoProfile",
                    "-NonInteractive",
                    "-Command",
                    "Get-Service | Select-Object Name,DisplayName,Status,StartType | ConvertTo-Json"
                ]
                proc = subprocess.run(ps, capture_output=True, text=True, timeout=20)
                services = []
                if proc.returncode == 0 and proc.stdout.strip():
                    try:
                        data = json.loads(proc.stdout)
                        if isinstance(data, dict):
                            data = [data]
                        if isinstance(data, list):
                            for s in data:
                                if isinstance(s, dict):
                                    services.append({
                                        "name": s.get("Name"),
                                        "displayName": s.get("DisplayName"),
                                        "status": s.get("Status"),
                                        "startType": s.get("StartType")
                                    })
                    except Exception:
                        services = []
                if not services:
                    # Fallback to sc query state= all
                    proc = subprocess.run(["sc", "query", "state=", "all"], capture_output=True, text=True, timeout=20)
                    txt = (proc.stdout or "")
                    # Best-effort parse: capture SERVICE_NAME and STATE
                    cur = None
                    for line in txt.splitlines():
                        m = re.match(r"\s*SERVICE_NAME:\s*(.+)\s*$", line)
                        if m:
                            if cur:
                                services.append(cur)
                            cur = {"name": m.group(1).strip()}
                            continue
                        m = re.match(r"\s*STATE\s*:\s*\d+\s+(\w+)\s*$", line)
                        if m and cur is not None:
                            cur["status"] = m.group(1).strip()
                    if cur:
                        services.append(cur)
            else:
                name = serviceName.strip()
                ps = [
                    "powershell",
                    "-NoProfile",
                    "-NonInteractive",
                    "-Command",
                    f"Get-Service -Name {json.dumps(name)} | Select-Object Name,DisplayName,Status,StartType,ServiceType,DependentServices,ServicesDependedOn | ConvertTo-Json -Depth 4"
                ]
                proc = subprocess.run(ps, capture_output=True, text=True, timeout=20)
                service = None
                if proc.returncode == 0 and proc.stdout.strip():
                    try:
                        service = json.loads(proc.stdout)
                    except Exception:
                        service = None
                if service is None:
                    # Not found or error: succeed with empty (inventory style) or fail? tool description doesn't specify NOT_FOUND for status.
                    service = {}
                services = service

        ended = _iso(_now())
        inv_row["status"] = "succeeded"
        inv_row["ended_at"] = ended
        inv_row["duration_ms"] = int((time.time() - t0) * 1000)
        inv_row["updated_at"] = ended

        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                k["last_used_at"] = ended
                k["updated_at"] = ended
                break
        _save("api_keys.json", api_keys)
        _save("tool_invocations.json", invocations)

        return {
            "invocation_id": inv_id,
            "action": action,
            "serviceName": serviceName,
            "result": services
        }
    except subprocess.TimeoutExpired:
        ended = _iso(_now())
        inv_row["status"] = "failed"
        inv_row["ended_at"] = ended
        inv_row["duration_ms"] = int((time.time() - t0) * 1000)
        inv_row["error_code"] = "TIMEOUT"
        inv_row["error_message"] = "Service query timed out."
        inv_row["updated_at"] = ended
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "Service query timed out.", error_code="TIMEOUT", invocation_id=inv_id)
    except Exception as e:
        ended = _iso(_now())
        inv_row["status"] = "failed"
        inv_row["ended_at"] = ended
        inv_row["duration_ms"] = int((time.time() - t0) * 1000)
        inv_row["error_code"] = "FAILED"
        inv_row["error_message"] = str(e)[:500]
        inv_row["updated_at"] = ended
        _save("tool_invocations.json", invocations)
        return _err("CONFLICT", "Failed to retrieve service info.", error_code="FAILED", invocation_id=inv_id)

def list_allowed_commands(allowedCommandSetId=None, status=None, commandType=None, commandName=None, search=None, limit=None, cursor=None, sortBy=None, sortOrder=None, includeDisabledSets=None, includeArgumentPolicy=None, includeTimestamps=None, includeIds=None, includeSetInfo=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0455000" if __import__("os").path.isdir("./environment_mix/0455000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import secrets
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _encode_cursor(obj):
        import base64
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii")

    def _decode_cursor(cur):
        import base64
        try:
            raw = base64.urlsafe_b64decode(cur.encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    t0 = time.time()
    invocations = _load("tool_invocations.json")
    api_keys = _load("api_keys.json")
    allowed_sets = _load("allowed_command_sets.json")
    allowed_cmds = _load("allowed_commands.json")

    # Ambient auth: choose active key
    api_key = None
    for k in api_keys:
        if k.get("status") == "active":
            api_key = k
            break
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available for this request")

    # Defaults
    if limit is None:
        limit = 50
    if sortBy is None:
        sortBy = "commandName"
    if sortOrder is None:
        sortOrder = "asc"
    if includeDisabledSets is None:
        includeDisabledSets = False
    if includeArgumentPolicy is None:
        includeArgumentPolicy = True
    if includeTimestamps is None:
        includeTimestamps = False
    if includeIds is None:
        includeIds = False
    if includeSetInfo is None:
        includeSetInfo = False

    # Validate types/enums
    if allowedCommandSetId is not None and not isinstance(allowedCommandSetId, str):
        return _err("VALIDATION_ERROR", "allowedCommandSetId must be a string")
    if allowedCommandSetId is not None:
        if not re.match(r"^wcmcp_acl_[0-9A-HJKMNP-TV-Z]{26}$", allowedCommandSetId):
            return _err("VALIDATION_ERROR", "allowedCommandSetId is not a valid id")
    if status is not None and status not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "Invalid status filter")
    if commandType is not None and commandType not in ("cmd", "powershell"):
        return _err("VALIDATION_ERROR", "Invalid commandType filter")
    if commandName is not None and not isinstance(commandName, str):
        return _err("VALIDATION_ERROR", "commandName must be a string")
    if search is not None and not isinstance(search, str):
        return _err("VALIDATION_ERROR", "search must be a string")
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sortBy not in ("commandName", "createdAt", "updatedAt"):
        return _err("VALIDATION_ERROR", "sortBy must be one of commandName, createdAt, updatedAt")
    if sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be 'asc' or 'desc'")
    for bname, bval in [("includeDisabledSets", includeDisabledSets), ("includeArgumentPolicy", includeArgumentPolicy), ("includeTimestamps", includeTimestamps), ("includeIds", includeIds), ("includeSetInfo", includeSetInfo)]:
        if not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be boolean")

    # Rate limit
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    window_start = now_dt - datetime.timedelta(minutes=1)
    recent = 0
    for inv in invocations:
        if inv.get("api_key_id") != api_key["id"]:
            continue
        cdt = _parse_dt(inv.get("created_at"))
        if cdt and cdt >= window_start:
            recent += 1
    if recent >= int(api_key.get("rate_limit_per_minute", 60)):
        inv_id = _ulid("wcmcp_inv_")
        now = _now_iso()
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key["id"],
            "tool_name": "list_allowed_commands",
            "request_params": {
                "allowedCommandSetId": allowedCommandSetId,
                "status": status,
                "commandType": commandType,
                "commandName": commandName,
                "search": search,
                "limit": limit,
                "cursor": cursor,
                "sortBy": sortBy,
                "sortOrder": sortOrder,
                "includeDisabledSets": includeDisabledSets,
                "includeArgumentPolicy": includeArgumentPolicy,
                "includeTimestamps": includeTimestamps,
                "includeIds": includeIds,
                "includeSetInfo": includeSetInfo
            },
            "status": "rejected",
            "started_at": None,
            "ended_at": now,
            "duration_ms": 0,
            "result_truncated": False,
            "error_code": "RATE_LIMIT",
            "error_message": "Rate limit exceeded",
            "client_ip": None,
            "created_at": now,
            "updated_at": now
        })
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Determine target set and authorization (FORBIDDEN concept -> use UNAUTHORIZED/CONFLICT codes we have)
    target_set_id = allowedCommandSetId or api_key.get("allowed_command_set_id")
    if not target_set_id:
        return _err("UNAUTHORIZED", "API key has no allowed command set")

    # Only allow listing another set if it matches caller's set (no admin model in schema)
    if allowedCommandSetId is not None and allowedCommandSetId != api_key.get("allowed_command_set_id"):
        # Must still log
        inv_id = _ulid("wcmcp_inv_")
        now = _now_iso()
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key["id"],
            "tool_name": "list_allowed_commands",
            "request_params": {
                "allowedCommandSetId": allowedCommandSetId,
                "status": status,
                "commandType": commandType,
                "commandName": commandName,
                "search": search,
                "limit": limit,
                "cursor": cursor,
                "sortBy": sortBy,
                "sortOrder": sortOrder,
                "includeDisabledSets": includeDisabledSets,
                "includeArgumentPolicy": includeArgumentPolicy,
                "includeTimestamps": includeTimestamps,
                "includeIds": includeIds,
                "includeSetInfo": includeSetInfo
            },
            "status": "rejected",
            "started_at": None,
            "ended_at": now,
            "duration_ms": 0,
            "result_truncated": False,
            "error_code": "FORBIDDEN",
            "error_message": "Not permitted to view the requested allowed command set",
            "client_ip": None,
            "created_at": now,
            "updated_at": now
        })
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Not permitted to view the requested allowed command set", error_code="FORBIDDEN")

    set_row = None
    for s in allowed_sets:
        if s.get("id") == target_set_id:
            set_row = s
            break
    if not set_row:
        # log but return empty? this is a read with missing reference; treat as NOT_FOUND
        inv_id = _ulid("wcmcp_inv_")
        now = _now_iso()
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key["id"],
            "tool_name": "list_allowed_commands",
            "request_params": {
                "allowedCommandSetId": allowedCommandSetId,
                "status": status,
                "commandType": commandType,
                "commandName": commandName,
                "search": search,
                "limit": limit,
                "cursor": cursor,
                "sortBy": sortBy,
                "sortOrder": sortOrder,
                "includeDisabledSets": includeDisabledSets,
                "includeArgumentPolicy": includeArgumentPolicy,
                "includeTimestamps": includeTimestamps,
                "includeIds": includeIds,
                "includeSetInfo": includeSetInfo
            },
            "status": "failed",
            "started_at": now,
            "ended_at": now,
            "duration_ms": 0,
            "result_truncated": False,
            "error_code": "NOT_FOUND",
            "error_message": "Allowed command set not found",
            "client_ip": None,
            "created_at": now,
            "updated_at": now
        })
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Allowed command set not found")

    if set_row.get("status") != "active" and not includeDisabledSets:
        # Return empty (read whose filter matches nothing) but log success
        inv_id = _ulid("wcmcp_inv_")
        now = _now_iso()
        invocations.append({
            "id": inv_id,
            "api_key_id": api_key["id"],
            "tool_name": "list_allowed_commands",
            "request_params": {
                "allowedCommandSetId": allowedCommandSetId,
                "status": status,
                "commandType": commandType,
                "commandName": commandName,
                "search": search,
                "limit": limit,
                "cursor": cursor,
                "sortBy": sortBy,
                "sortOrder": sortOrder,
                "includeDisabledSets": includeDisabledSets,
                "includeArgumentPolicy": includeArgumentPolicy,
                "includeTimestamps": includeTimestamps,
                "includeIds": includeIds,
                "includeSetInfo": includeSetInfo
            },
            "status": "succeeded",
            "started_at": now,
            "ended_at": now,
            "duration_ms": 0,
            "result_truncated": False,
            "error_code": None,
            "error_message": None,
            "client_ip": None,
            "created_at": now,
            "updated_at": now
        })
        api_key["last_used_at"] = now
        api_key["updated_at"] = now
        _save("api_keys.json", api_keys)
        _save("tool_invocations.json", invocations)
        return {"items": [], "meta": {"total": 0, "has_more": False, "next_cursor": None}}

    # Log invocation (received->running->succeeded) even for reads
    inv_id = _ulid("wcmcp_inv_")
    created_at = _now_iso()
    inv = {
        "id": inv_id,
        "api_key_id": api_key["id"],
        "tool_name": "list_allowed_commands",
        "request_params": {
            "allowedCommandSetId": allowedCommandSetId,
            "status": status,
            "commandType": commandType,
            "commandName": commandName,
            "search": search,
            "limit": limit,
            "cursor": cursor,
            "sortBy": sortBy,
            "sortOrder": sortOrder,
            "includeDisabledSets": includeDisabledSets,
            "includeArgumentPolicy": includeArgumentPolicy,
            "includeTimestamps": includeTimestamps,
            "includeIds": includeIds,
            "includeSetInfo": includeSetInfo
        },
        "status": "received",
        "started_at": None,
        "ended_at": None,
        "duration_ms": None,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "client_ip": None,
        "created_at": created_at,
        "updated_at": created_at
    }
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    started = _now_iso()
    inv["status"] = "running"
    inv["started_at"] = started
    inv["updated_at"] = started
    _save("tool_invocations.json", invocations)

    # Apply filters
    rows = []
    for r in allowed_cmds:
        if r.get("allowed_command_set_id") != target_set_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if commandType is not None and r.get("command_type") != commandType:
            continue
        if commandName is not None and r.get("command_name") != commandName:
            continue
        if search is not None:
            hay = (r.get("command_name") or "") + "\n" + (r.get("description") or "")
            if search.lower() not in hay.lower():
                continue
        rows.append(r)

    # Sorting
    def _sort_key(r):
        if sortBy == "commandName":
            return (r.get("command_name") or "").lower()
        if sortBy == "createdAt":
            dt = _parse_dt(r.get("created_at"))
            return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        dt = _parse_dt(r.get("updated_at"))
        return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    rows.sort(key=_sort_key, reverse=(sortOrder == "desc"))

    # Cursor pagination: cursor encodes {"offset": int}
    offset = 0
    if cursor:
        obj = _decode_cursor(cursor)
        if not obj or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
            ended = _now_iso()
            inv["status"] = "rejected"
            inv["ended_at"] = ended
            inv["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
            inv["updated_at"] = ended
            inv["error_code"] = "VALIDATION_ERROR"
            inv["error_message"] = "Invalid cursor"
            _save("tool_invocations.json", invocations)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        offset = obj["offset"]

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"offset": next_offset}) if has_more else None

    # Shape response items
    items = []
    for r in page:
        item = {
            "commandName": r.get("command_name"),
            "commandType": r.get("command_type"),
            "status": r.get("status"),
            "description": r.get("description")
        }
        if includeArgumentPolicy:
            item["argumentPolicy"] = r.get("argument_policy")
            item["argumentRegex"] = r.get("argument_regex")
        if includeIds:
            item["id"] = r.get("id")
            item["allowedCommandSetId"] = r.get("allowed_command_set_id")
        if includeTimestamps:
            item["createdAt"] = r.get("created_at")
            item["updatedAt"] = r.get("updated_at")
        if includeSetInfo:
            item["allowedCommandSet"] = {
                "id": set_row.get("id"),
                "name": set_row.get("name"),
                "status": set_row.get("status"),
                "defaultTimeoutMs": set_row.get("default_timeout_ms"),
                "maxTimeoutMs": set_row.get("max_timeout_ms"),
                "allowAnyWorkingDir": set_row.get("allow_any_working_dir"),
                "allowPowershell": set_row.get("allow_powershell"),
            }
        items.append(item)

    ended = _now_iso()
    inv["status"] = "succeeded"
    inv["ended_at"] = ended
    inv["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
    inv["updated_at"] = ended
    _save("tool_invocations.json", invocations)

    api_key["last_used_at"] = ended
    api_key["updated_at"] = ended
    _save("api_keys.json", api_keys)

    return {"items": items, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}, "invocationId": inv_id}

def get_current_identity(includeQuota=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0455000" if __import__("os").path.isdir("./environment_mix/0455000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64u_enc(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _log_invocation(tool_name, api_key_id, request_params, status, error_code=None, error_message=None, started_at=None, ended_at=None, duration_ms=None, result_truncated=False):
        invocations = _load("tool_invocations.json")
        now = _now_iso()
        # generate an id if missing; for identity tool we still log with a generated id
        inv_id = "wcmcp_inv_" + _b64u_enc(os.urandom(20))[:26].upper()
        row = {
            "id": inv_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "status": status,
            "started_at": started_at,
            "ended_at": ended_at,
            "duration_ms": duration_ms,
            "result_truncated": bool(result_truncated),
            "error_code": error_code,
            "error_message": error_message,
            "client_ip": None,
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row

    t0 = time.time()

    # Validate params
    if includeQuota is None:
        includeQuota = True
    if not isinstance(includeQuota, bool):
        # No api key context to associate; attempt to find any active key to log under; else unauthorized without logging.
        keys = _load("api_keys.json")
        active_key = next((k for k in keys if k.get("status") == "active"), None)
        if active_key:
            _log_invocation(
                "get_current_identity",
                active_key.get("id"),
                {"includeQuota": includeQuota},
                "rejected",
                error_code="VALIDATION_ERROR",
                error_message="includeQuota must be a boolean",
                started_at=None,
                ended_at=_now_iso(),
                duration_ms=int((time.time() - t0) * 1000),
            )
        return _err("VALIDATION_ERROR", "includeQuota must be a boolean")

    # Ambient auth: resolve a usable api key context from store.
    keys = _load("api_keys.json")
    sets = _load("allowed_command_sets.json")
    set_by_id = {s.get("id"): s for s in sets if isinstance(s, dict)}

    api_key = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        acs = set_by_id.get(k.get("allowed_command_set_id"))
        if acs and acs.get("status") in ("active", "disabled"):
            api_key = k
            break

    if api_key is None:
        # No authenticated context can be resolved
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    # Apply rate limit before proceeding (counts all tool_invocations in last rolling minute).
    invocations = _load("tool_invocations.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    window_start = now_dt - datetime.timedelta(minutes=1)
    recent = 0
    for inv in invocations:
        if not isinstance(inv, dict):
            continue
        if inv.get("api_key_id") != api_key.get("id"):
            continue
        cdt = _parse_dt(inv.get("created_at"))
        if cdt and cdt >= window_start and cdt <= now_dt:
            recent += 1
    if isinstance(api_key.get("rate_limit_per_minute"), int) and recent >= api_key.get("rate_limit_per_minute"):
        _log_invocation(
            "get_current_identity",
            api_key.get("id"),
            {"includeQuota": includeQuota},
            "rejected",
            error_code="RATE_LIMIT",
            error_message="Rate limit exceeded",
            ended_at=_now_iso(),
            duration_ms=int((time.time() - t0) * 1000),
        )
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Key revoked? (Shouldn't happen since we selected active, but enforce business rule)
    if api_key.get("status") != "active":
        _log_invocation(
            "get_current_identity",
            api_key.get("id"),
            {"includeQuota": includeQuota},
            "rejected",
            error_code="KEY_REVOKED",
            error_message="API key revoked",
            ended_at=_now_iso(),
            duration_ms=int((time.time() - t0) * 1000),
        )
        return _err("UNAUTHORIZED", "API key revoked", reason="KEY_REVOKED")

    # Update last_used_at on successful authenticated request
    api_key["last_used_at"] = _now_iso()
    api_key["updated_at"] = _now_iso()
    # persist api_keys update
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            keys[i] = api_key
            break
    _save("api_keys.json", keys)

    quota = None
    if includeQuota:
        # concurrent executions: status in ('queued','running')
        execs = _load("command_executions.json")
        concurrent = 0
        for e in execs:
            if not isinstance(e, dict):
                continue
            if e.get("api_key_id") == api_key.get("id") and e.get("status") in ("queued", "running"):
                concurrent += 1
        quota = {
            "rateLimitPerMinute": api_key.get("rate_limit_per_minute"),
            "rollingMinuteUsed": recent,  # prior invocations in window (excluding this call, since it isn't logged yet)
            "rollingMinuteRemaining": None if not isinstance(api_key.get("rate_limit_per_minute"), int) else max(api_key.get("rate_limit_per_minute") - recent, 0),
            "maxConcurrentExecutions": api_key.get("max_concurrent_executions"),
            "currentConcurrentExecutions": concurrent,
        }

    # Log successful read tool invocation
    _log_invocation(
        "get_current_identity",
        api_key.get("id"),
        {"includeQuota": includeQuota},
        "succeeded",
        started_at=_now_iso(),
        ended_at=_now_iso(),
        duration_ms=int((time.time() - t0) * 1000),
    )

    return {
        "apiKeyId": api_key.get("id"),
        "name": api_key.get("name"),
        "status": api_key.get("status"),
        "allowedCommandSetId": api_key.get("allowed_command_set_id"),
        "scopes": {
            "canViewAuditLogs": True,
            "canViewExecutionHistory": True,
            "canExecuteCommands": True,
            "canExecutePowershell": True,  # actual enforcement happens on execute_powershell via policy
        },
        "quota": quota,
    }

def list_tool_invocations(status=None, toolName=None, since=None, until=None, limit=None, cursor=None, sortOrder=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0455000" if __import__("os").path.isdir("./environment_mix/0455000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64u_enc(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64u_dec(s):
        if not isinstance(s, str):
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            return base64.urlsafe_b64decode(s + pad)
        except Exception:
            return None

    def _log_invocation(tool_name, api_key_id, request_params, status, error_code=None, error_message=None, ended_at=None, duration_ms=None):
        invocations = _load("tool_invocations.json")
        now = _now_iso()
        inv_id = "wcmcp_inv_" + _b64u_enc(os.urandom(20))[:26].upper()
        row = {
            "id": inv_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "status": status,
            "started_at": None,
            "ended_at": ended_at,
            "duration_ms": duration_ms,
            "result_truncated": False,
            "error_code": error_code,
            "error_message": error_message,
            "client_ip": None,
            "created_at": now,
            "updated_at": now,
        }
        invocations.append(row)
        _save("tool_invocations.json", invocations)
        return row

    t0 = time.time()

    # Validate inputs
    allowed_status = {"received", "running", "succeeded", "failed", "rejected"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status")

    if toolName is not None and not isinstance(toolName, str):
        return _err("VALIDATION_ERROR", "toolName must be a string")

    since_dt = None
    until_dt = None
    if since is not None:
        if not isinstance(since, str) or _parse_dt(since) is None:
            return _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string")
        since_dt = _parse_dt(since)
    if until is not None:
        if not isinstance(until, str) or _parse_dt(until) is None:
            return _err("VALIDATION_ERROR", "until must be an RFC3339 date-time string")
        until_dt = _parse_dt(until)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if sortOrder is None:
        sortOrder = "desc"
    if not isinstance(sortOrder, str) or sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be 'asc' or 'desc'")

    # Ambient auth: require some active key
    keys = _load("api_keys.json")
    api_key = next((k for k in keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if api_key is None:
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    # Rate limit check
    invocations_all = _load("tool_invocations.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    window_start = now_dt - datetime.timedelta(minutes=1)
    recent = 0
    for inv in invocations_all:
        if not isinstance(inv, dict):
            continue
        if inv.get("api_key_id") != api_key.get("id"):
            continue
        cdt = _parse_dt(inv.get("created_at"))
        if cdt and cdt >= window_start and cdt <= now_dt:
            recent += 1
    if isinstance(api_key.get("rate_limit_per_minute"), int) and recent >= api_key.get("rate_limit_per_minute"):
        _log_invocation(
            "list_tool_invocations",
            api_key.get("id"),
            {"status": status, "toolName": toolName, "since": since, "until": until, "limit": limit, "cursor": cursor, "sortOrder": sortOrder},
            "rejected",
            error_code="RATE_LIMIT",
            error_message="Rate limit exceeded",
            ended_at=_now_iso(),
            duration_ms=int((time.time() - t0) * 1000),
        )
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Cursor: base64url encoded JSON {"ts": "...", "id":"..."}
    cursor_ts = None
    cursor_id = None
    if cursor is not None:
        if not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string")
        raw = _b64u_dec(cursor)
        if raw is None:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        try:
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(obj, dict) or "ts" not in obj or "id" not in obj:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        cursor_ts = _parse_dt(obj.get("ts"))
        cursor_id = obj.get("id")
        if cursor_ts is None or not isinstance(cursor_id, str):
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # Filter visible to caller: api_key_id matches
    rows = []
    for inv in invocations_all:
        if not isinstance(inv, dict):
            continue
        if inv.get("api_key_id") != api_key.get("id"):
            continue
        if status is not None and inv.get("status") != status:
            continue
        if toolName is not None and inv.get("tool_name") != toolName:
            continue
        cdt = _parse_dt(inv.get("created_at"))
        if since_dt and (cdt is None or cdt < since_dt):
            continue
        if until_dt and (cdt is None or cdt >= until_dt):
            continue
        rows.append(inv)

    # Sort by created_at, tie-breaker by id for stable pagination
    def _key(inv):
        dt = _parse_dt(inv.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, inv.get("id") or "")

    rows.sort(key=_key, reverse=(sortOrder == "desc"))

    # Apply cursor (created_at, id) exclusive
    if cursor_ts is not None:
        filtered = []
        for inv in rows:
            dt = _parse_dt(inv.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            iid = inv.get("id") or ""
            if sortOrder == "desc":
                # want items strictly older than cursor (dt,id) in desc order
                if (dt, iid) < (cursor_ts, cursor_id):
                    filtered.append(inv)
            else:
                # asc: strictly newer than cursor
                if (dt, iid) > (cursor_ts, cursor_id):
                    filtered.append(inv)
        rows = filtered

    page = rows[:limit]
    has_more = len(rows) > len(page)
    next_cursor = None
    if page:
        last = page[-1]
        next_obj = {"ts": last.get("created_at"), "id": last.get("id")}
        next_cursor = _b64u_enc(json.dumps(next_obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8"))

    # Update last_used_at and log invocation success
    api_key["last_used_at"] = _now_iso()
    api_key["updated_at"] = _now_iso()
    for i, k in enumerate(keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            keys[i] = api_key
            break
    _save("api_keys.json", keys)

    _log_invocation(
        "list_tool_invocations",
        api_key.get("id"),
        {"status": status, "toolName": toolName, "since": since, "until": until, "limit": limit, "cursor": cursor, "sortOrder": sortOrder},
        "succeeded",
        ended_at=_now_iso(),
        duration_ms=int((time.time() - t0) * 1000),
    )

    return {
        "data": page,
        "meta": {
            "limit": limit,
            "total": len(rows) + (0 if cursor_ts is None else None),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_order": sortOrder,
