def list_command_executions(status=None, executionType=None, invocationId=None, since=None, until=None, limit=None, cursor=None, sortOrder=None, includeOutputPreview=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0455000" if __import__("os").path.isdir("./environment_mix/0455000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _count_invocations_last_minute(invocations, api_key_id, now_dt):
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in invocations:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt

    def _b64u_enc(s):
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("ascii").rstrip("=")

    def _b64u_dec(s):
        if not isinstance(s, str) or not s:
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            return base64.urlsafe_b64decode(s + pad).decode("utf-8")
        except Exception:
            return None

    t0 = time.time()
    now_dt = _now()
    now_iso = _iso(now_dt)

    # Validate filters (relaxed for IDs: accept any string)
    valid_status = {"queued", "running", "succeeded", "failed", "rejected", "timed_out"}
    if status is not None and (not isinstance(status, str) or status not in valid_status):
        return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed, rejected, timed_out")
    valid_type = {None, "cmd", "powershell"}
    if executionType is not None and (not isinstance(executionType, str) or executionType not in valid_type):
        return _err("VALIDATION_ERROR", "executionType must be one of cmd, powershell")
    if invocationId is not None and (not isinstance(invocationId, str) or not invocationId):
        return _err("VALIDATION_ERROR", "invocationId must be a non-empty string when provided")

    since_dt = _parse_dt(since)
    if since is not None and since_dt is None:
        return _err("VALIDATION_ERROR", "since must be an RFC3339 date-time string")
    until_dt = _parse_dt(until)
    if until is not None and until_dt is None:
        return _err("VALIDATION_ERROR", "until must be an RFC3339 date-time string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be 'asc' or 'desc'")

    if includeOutputPreview is None:
        includeOutputPreview = False
    if not isinstance(includeOutputPreview, bool):
        return _err("VALIDATION_ERROR", "includeOutputPreview must be a boolean")

    api_keys = _load("api_keys.json")
    invocations = _load("tool_invocations.json")
    executions = _load("command_executions.json")

    api_key = next((k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"), None)
    if api_key is None:
        return _err("UNAUTHORIZED", "No active API key available to authorize this request.")
    api_key_id = api_key.get("id")

    rl = api_key.get("rate_limit_per_minute")
    if not isinstance(rl, int):
        rl = 60
    if _count_invocations_last_minute(invocations, api_key_id, now_dt) > rl:
        return _err("RATE_LIMIT", "Rate limit exceeded.", error_code="RATE_LIMIT")

    # Log this read
    log_id = "wcmcp_inv_read_" + now_dt.strftime("%Y%m%d%H%M%S%f")
    invocations.append({
        "id": log_id,
        "api_key_id": api_key_id,
        "tool_name": "list_command_executions",
        "request_params": {
            "status": status,
            "executionType": executionType,
            "invocationId": invocationId,
            "since": since,
            "until": until,
            "limit": limit,
            "cursor": cursor,
            "sortOrder": sortOrder,
            "includeOutputPreview": includeOutputPreview
        },
        "status": "succeeded",
        "started_at": now_iso,
        "ended_at": now_iso,
        "duration_ms": 0,
        "result_truncated": False,
        "error_code": None,
        "error_message": None,
        "client_ip": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    _save("tool_invocations.json", invocations)

    # Apply filters & visibility (owned by caller)
    filtered = []
    for e in executions:
        if not isinstance(e, dict):
            continue
        if e.get("api_key_id") != api_key_id:
            continue
        if status is not None and e.get("status") != status:
            continue
        if invocationId is not None and e.get("invocation_id") != invocationId:
            continue
        if executionType is not None:
            want = "execute_command" if executionType == "cmd" else "execute_powershell"
            if e.get("execution_type") != want:
                continue
        created = _parse_dt(e.get("created_at"))
        if since_dt is not None and (created is None or created < since_dt):
            continue
        if until_dt is not None and (created is None or created >= until_dt):
            continue
        filtered.append(e)

    # Sort
    def _created_key(r):
        dt = _parse_dt(r.get("created_at"))
        return dt or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    filtered.sort(key=_created_key, reverse=(sortOrder == "desc"))

    # Cursor: opaque token; accept raw ids too
    start_idx = 0
    if cursor:
        decoded = _b64u_dec(cursor)
        token = decoded if decoded is not None else cursor
        for i, r in enumerate(filtered):
            if r.get("id") == token:
                start_idx = i + 1
                break

    page = filtered[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(filtered)
    next_cursor = _b64u_enc(page[-1]["id"]) if (has_more and page) else None

    # Strip previews unless requested
    items = []
    for r in page:
        rr = dict(r)
        if not includeOutputPreview:
            rr.pop("stdout_preview", None)
            rr.pop("stderr_preview", None)
        items.append(rr)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "executions": items,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_order": sortOrder,
            "latency_ms": latency_ms
        }
    }

