def cancel_command_execution(executionId, reason=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0455000" if __import__("os").path.isdir("./environment_mix/0455000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(26))

    def _pick_any_active_api_key(api_keys):
        for k in api_keys:
            if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str):
                return k
        return None

    t0 = time.time()
    now_dt = _now()
    now_iso = _iso(now_dt)

    if not isinstance(executionId, str) or not executionId:
        return _err("VALIDATION_ERROR", "executionId must be a non-empty string")
    if not executionId.startswith("wcmcp_exec_"):
        return _err("VALIDATION_ERROR", "executionId must start with 'wcmcp_exec_'")
    if reason is not None and (not isinstance(reason, str) or len(reason) > 500):
        return _err("VALIDATION_ERROR", "reason must be a string up to 500 characters when provided")

    api_keys = _load("api_keys.json")
    invocations = _load("tool_invocations.json")
    executions = _load("command_executions.json")

    api_key = _pick_any_active_api_key(api_keys)
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key context available for cancellation.")

    row = next((r for r in executions if isinstance(r, dict) and r.get("id") == executionId), None)
    if not row:
        # Return empty rather than NOT_FOUND per read behavior; but this is mutation, so NOT_FOUND.
        return _err("NOT_FOUND", "Execution not found.", execution_id=executionId)

    if row.get("api_key_id") != api_key.get("id"):
        return _err("NOT_FOUND", "Execution not found.", execution_id=executionId)

    # If terminal, idempotently return current record without changes
    if row.get("status") in ("succeeded", "failed", "rejected", "timed_out"):
        return {"data": row, "meta": {"changed": False}}

    # Only queued/running can be canceled; transition to rejected (queued) or failed (running) isn't defined.
    # Use allowed transition queued->rejected; running has no canceled state, so set to failed with error metadata.
    ended_iso = now_iso
    if row.get("status") == "queued":
        row["status"] = "rejected"
        row["ended_at"] = ended_iso
        row["updated_at"] = ended_iso
    elif row.get("status") == "running":
        row["status"] = "failed"
        row["ended_at"] = ended_iso
        row["updated_at"] = ended_iso
    else:
        return _err("INVALID_TRANSITION", "Execution is not cancelable from its current status.", execution_id=executionId, status=row.get("status"))

    # Update parent invocation consistently if it exists and is not terminal
    inv = next((i for i in invocations if isinstance(i, dict) and i.get("id") == row.get("invocation_id")), None)
    if inv and inv.get("status") in ("received", "running"):
        inv["status"] = "failed" if row["status"] == "failed" else "rejected"
        inv["error_code"] = "CANCELED"
        inv["error_message"] = ("Canceled by client." + (f" Reason: {reason}" if reason else ""))
        if inv.get("started_at") is None:
            inv["started_at"] = now_iso
        inv["ended_at"] = now_iso
        try:
            st = _parse_dt(inv.get("started_at")) or now_dt
            en = _parse_dt(inv.get("ended_at")) or now_dt
            inv["duration_ms"] = int(max(0, (en - st).total_seconds() * 1000))
        except Exception:
            inv["duration_ms"] = int((time.time() - t0) * 1000)
        inv["updated_at"] = now_iso

    _save("command_executions.json", executions)
    _save("tool_invocations.json", invocations)

    return {"data": row, "meta": {"changed": True, "reason": reason}}
